        if stok.get(item, 0) < qty:
            print(f"stok {item} kurang")
        else:
            stok[item] -= qty
    elif aksi == "laporan":
        ada = [(k, v) for k, v in sorted(stok.items()) if v > 0]
        if not ada:
            print("(gudang kosong)")
        for k, v in ada:
